; Play frame work
; $7b2b-$7b57

; Frame work of the play IRQ at split 0: flash, cover, magic wall time, cave time, sound and scroll. Even frames show the screen that was drawn last. Odd frames draw the other screen at $9E00.
play_frame_irq
        lda irq_split_index
        beq play_frame_irq_run
        rts
play_frame_irq_run
        jsr flash_screen
        jsr animate_cover
        jsr count_magic_wall_time
        jsr update_clock
        jsr update_sound
        inc frame_counter
        jsr update_scroll
        lda frame_counter
        and #$01
        bne play_frame_irq_draw
        lda game_d018_value             ; Show the drawn screen, then draw into the other screen next time.
        sta irq_d018_values
        eor #$80
        sta game_d018_value
        rts
play_frame_irq_draw
        jmp $9e00
